"""Data profile of data/dev, generated by script so it is reproducible and diffable.

    python -m mlkit.profile          # writes reports/data_profile.md and .json

Univariate facts (types, missing values, ranges, stability over time) use all of
data/dev. Feature-target strength uses the exploration period only (see
mlkit/dataquality.py). This is the ONLY way an agent sees feature-target
relations: the data-analyst role has no direct access to the label file.
"""
from __future__ import annotations

import json
import sys

import numpy as np
import pandas as pd

from . import config, core, dataquality as dq


def column_summary(s: pd.Series, entry: dict) -> dict:
    if pd.api.types.is_bool_dtype(s):          # True/False: a category, not a number (XP2)
        s = s.astype(str)
    num = pd.to_numeric(s, errors="coerce")
    nonnull = s.notna()
    numeric = nonnull.any() and num[nonnull].notna().mean() >= 0.99
    out = {"type": "numeric" if numeric else "categorical", "missing": float(s.isna().mean()),
           "distinct": int(s.nunique(dropna=True))}
    flags = []
    if out["distinct"] <= 1:
        flags.append("constante")
    if out["missing"] > 0.5:
        flags.append("plus de 50 % missing")
    if numeric:
        v = num.dropna()
        if len(v):
            out.update(min=float(v.min()), p01=float(v.quantile(0.01)), median=float(v.median()),
                       p99=float(v.quantile(0.99)), max=float(v.max()))
            for sentinel in dq.SENTINELS:
                share = float((v == sentinel).mean())
                if share > 0.05 and sentinel in (v.min(), v.max()):
                    flags.append(f"value {sentinel} at an endpoint ({share:.0%}): sentinel?")
            if v.max() > 20 * max(v.quantile(0.99), 1e-9):
                flags.append("extreme tail (max > 20 × p99)")
    else:
        top = s.astype(str).value_counts(normalize=True).head(5)
        out["top"] = {k: float(v) for k, v in top.items()}
        if out["distinct"] > 50:
            flags.append(f"high cardinality ({out['distinct']})")
    integer_like = numeric and bool((num.dropna() % 1 == 0).all())
    if (not numeric or integer_like) and out["distinct"] > 0.9 * nonnull.sum() and nonnull.sum() > 100:
        flags.append("quasi unique : identifiant ?")
    if entry is not None and entry.get("excluded_by"):
        flags = []                      # identifiers, time column, excluded columns: expected shape
    if entry is None:
        flags.append("MISSING DU REGISTRY (D2)")
    elif "meaning" not in entry:
        flags.append("undocumented meaning")
    out["flags"] = flags
    return out


def histogram(s: pd.Series, numeric: bool) -> dict:
    """Small distribution summary for the HTML data dossier."""
    if numeric and not pd.api.types.is_bool_dtype(s):
        v = pd.to_numeric(s, errors="coerce").dropna()
        if not len(v):
            return {}
        lo, hi = float(v.quantile(0.01)), float(v.quantile(0.99))
        if hi <= lo:
            return {"kind": "num", "edges": [lo, hi], "counts": [int(len(v))], "below": 0, "above": 0}
        counts, edges = np.histogram(v.clip(lo, hi), bins=20, range=(lo, hi))
        return {"kind": "num", "edges": [float(e) for e in edges], "counts": [int(c) for c in counts],
                "below": int((v < lo).sum()), "above": int((v > hi).sum())}
    top = s.astype("string").fillna("(missing)").value_counts(normalize=True)
    return {"kind": "cat", "top": {str(k): float(x) for k, x in top.head(12).items()},
            "other": float(top.iloc[12:].sum()) if len(top) > 12 else 0.0}


def main(argv=None) -> int:
    frame = config.load_frame()
    spec, registry = frame["spec"], config.load_features()
    q = dq.quality_settings()
    df = dq.read_features(spec)
    labels = pd.read_csv(config.DEV_DIR / "labels.csv.gz")

    cols = [c for c in df.columns if c not in ("_month",)]
    summary = {c: column_summary(df[c], registry.get(c)) for c in cols}
    stab = dq.stability(df, registry, spec)
    strength, expl_end = dq.univariate_strength(df, labels, spec)
    contract = dq.contract_violations(df, registry, q.get("min_rows_month", 200))

    volume = dq.months_with_volume(df, q.get("min_rows_month", 200))
    sub = df[df["_month"].isin(volume)]
    for c in cols:
        summary[c]["psi_by_window"] = stab.get(c, {}).get("per_window", {})
        miss = sub[c].isna().groupby(sub["_month"]).mean() if len(sub) else pd.Series(dtype=float)
        if miss.max() > 0 if len(miss) else False:
            summary[c]["missing_by_month"] = {str(k): round(float(v), 4) for k, v in miss.items()}
        summary[c]["hist"] = histogram(df[c], summary[c]["type"] == "numeric")
    for c in cols:
        summary[c]["psi_max"] = stab.get(c, {}).get("max")
        summary[c]["strength"] = strength.get(c)
        entry = registry.get(c, {})
        if summary[c]["psi_max"] is not None and summary[c]["psi_max"] > q.get("psi_warn", 0.1):
            summary[c]["flags"].append(f"unstable over time (PSI {summary[c]['psi_max']:.2f})")
        st = summary[c]["strength"]
        if st is not None and st >= q.get("univariate_auc_stop", 0.8):
            avail = entry.get("available", "?")
            summary[c]["flags"].append(f"individually predictive of the target (AUC {st:.2f}) — leakage?" if avail == "origination"
                                       else f"individually predictive of the target (AUC {st:.2f}) — expected: {avail}")
        if c in contract:
            summary[c]["flags"] += [f"contract : {p}" for p in contract[c]]

    merged = df[[spec["id_col"], "_month"]].merge(labels, on=spec["id_col"], how="inner")
    by_month = merged.groupby("_month").agg(n=(spec["target_col"], "size"), rate=(spec["target_col"], "mean"))

    config.REPORTS_DIR.mkdir(exist_ok=True)
    payload = {"frame_hash": config.frame_hash(), "rows": int(len(df)),
               "data_hash": "-".join(config.sha256_file(p) for p in core.dev_files()),
               "months": [str(df["_month"].min()), str(df["_month"].max())],
               "exploration_period_end": expl_end, "columns": summary,
               "target_by_month": {str(k): {"n": int(v["n"]), "rate": float(v["rate"])} for k, v in by_month.iterrows()}}
    (config.REPORTS_DIR / "data_profile.json").write_text(json.dumps(payload, ensure_ascii=False, indent=1), encoding="utf-8")

    def fmt(x, pat="{:.2f}"):
        return "" if x is None or (isinstance(x, float) and np.isnan(x)) else pat.format(x)

    lines = [
        "# Development data profile", "",
        f"- {len(df):,} rows, {payload['months'][0]} → {payload['months'][1]} · frame {payload['frame_hash']}",
        f"- Feature-target relationships calculated **through {expl_end} only** (exploration period).",
        f"- Flagged columns: {sum(1 for c in cols if summary[c]['flags'])} over {len(cols)}.", "",
        "## Flagged columns", "",
        "| column | available | type | missing | max PSI | individual strength | signals |", "|---|---|---|---|---|---|---|",
    ]
    order = sorted(cols, key=lambda c: (-len(summary[c]["flags"]), c))
    for c in order:
        s = summary[c]
        if not s["flags"]:
            continue
        lines.append(f"| `{c}` | {registry.get(c, {}).get('available', '—')} | {s['type']} | {s['missing']:.1%} | "
                     f"{fmt(s['psi_max'])} | {fmt(s['strength'])} | {'<br>'.join(s['flags'])} |")
    lines += ["", "## All columns", "",
              "| column | type | missing | distinct | min | median | max | max PSI | individual strength |",
              "|---|---|---|---|---|---|---|---|---|"]
    for c in sorted(cols):
        s = summary[c]
        lines.append(f"| `{c}` | {s['type']} | {s['missing']:.1%} | {s['distinct']} | {fmt(s.get('min'), '{:g}')} | "
                     f"{fmt(s.get('median'), '{:g}')} | {fmt(s.get('max'), '{:g}')} | {fmt(s['psi_max'])} | {fmt(s['strength'])} |")
    lines += ["", "## Target par months", "", "A break here concerns framing (origination policy, loan maturity), not a minor detail.", "",
              "| month | loans | default rate |", "|---|---|---|"]
    lines += [f"| {k} | {int(v['n'])} | {v['rate']:.1%} |" for k, v in by_month.iterrows()]
    (config.REPORTS_DIR / "data_profile.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    flagged = [c for c in order if summary[c]["flags"]]
    print(f"profile written: reports/data_profile.md · {len(flagged)} flagged columns"
          + (f" ({', '.join(flagged[:8])}{' …' if len(flagged) > 8 else ''})" if flagged else ""))
    from . import render
    render.safe_render()
    return 0


if __name__ == "__main__":
    sys.exit(main())
